function mk(seed){var s=seed>>>0;return function(){s=(s+0x6D2B79F5)>>>0;var t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
var N=26;
var AA='ACDEFGHIKLMNPQRSTVWY';
var rnd=mk(7);
var seqs=[[],[]];
for(var k=0;k<2;k++){for(var i=0;i<N;i++){seqs[k].push(AA[Math.floor(rnd()*20)]);}}
function smooth(a){var o=[];for(var i=0;i<a.length;i++){var s=0,c=0;for(var j=-2;j<=2;j++){if(a[i+j]!==undefined){s+=a[i+j];c++;}}o.push(s/c);}return o;}
function mkDesign(base,dip,seed,m){var r=mk(seed);var nx=[],ny=[];for(var i=0;i<N;i++){nx.push(r()*2-1);ny.push(r()*2-1);}nx=smooth(nx);ny=smooth(ny);var pl=[];for(var i=0;i<N;i++){var v=base+6*Math.sin(i*0.7+seed)+(r()-0.5)*6;if(i>=11&&i<=15)v-=dip;pl.push(Math.max(30,Math.min(98,v)));}var mean=0;for(var i=0;i<N;i++)mean+=pl[i];mean/=N;return{nx:nx,ny:ny,pl:pl,vals:[mean,m[0],m[1],m[2]]};}
var designs=[mkDesign(60,12,3,[17.8,3.9,2.4]),mkDesign(91,10,11,[6.2,1.1,0.7])];
var metrics=[{n:'mean pLDDT',max:100,thr:80,hi:true,u:'',lab:'> 80'},{n:'interface PAE',max:30,thr:10,hi:false,u:' Å',lab:'< 10 Å'},{n:'backbone RMSD',max:5,thr:2,hi:false,u:' Å',lab:'< 2 Å'},{n:'motif RMSD',max:3,thr:1.5,hi:false,u:' Å',lab:'< 1.5 Å'}];
function cl(x){return x<0?0:x>1?1:x;}
function ease(x){x=cl(x);return x*x*(3-2*x);}
function afc(v){return v>90?'#1d4ed8':v>70?'#38bdf8':v>50?'#eab308':'#f97316';}
function draw(ctx,W,H,time,dt){
ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);
var T=10;var t=time%T;var di=Math.floor(t/5);var lt=t%5;var D=designs[di];
var pass=di===1;
ctx.font='12px sans-serif';ctx.textBaseline='middle';
var names=['RFdiffusion backbone','MPNN sequence','RF3 / AF3 refold','compare'];
var stage=lt<1.1?0:lt<2.0?1:lt<3.4?2:3;
var bw=(W-24-3*14)/4;
for(var i=0;i<4;i++){var x=12+i*(bw+14);var on=i===stage;ctx.fillStyle=on?'#f3e8ff':'#f6f6f8';ctx.strokeStyle=on?'#7c3aed':'#bbbbc2';ctx.lineWidth=on?2:1;ctx.beginPath();ctx.rect(x,10,bw,28);ctx.fill();ctx.stroke();ctx.fillStyle='#1a1a1d';ctx.textAlign='center';ctx.fillText(names[i],x+bw/2,24);if(i<3){ctx.strokeStyle='#1a1a1d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+bw+2,24);ctx.lineTo(x+bw+12,24);ctx.stroke();}}
var px=12,py=76,pw=W*0.56,ph=H-76-92;
ctx.strokeStyle='#d4d4d8';ctx.lineWidth=1;ctx.strokeRect(px,py,pw,ph);
ctx.textAlign='left';ctx.fillStyle='#1a1a1d';ctx.fillText('Design ' + (di+1) + ' of 2',px+6,py-12);
var bx=[],by=[];
for(var i=0;i<N;i++){var u=i/(N-1);bx.push(px+pw*0.5+pw*0.3*Math.sin(u*Math.PI*3)*(0.6+0.4*Math.cos(u*3)));by.push(py+ph*0.08+ph*0.84*u+ph*0.05*Math.sin(u*Math.PI*7));}
var grow=ease(lt/1.0);var nShow=Math.floor(grow*(N-1))+1;
ctx.strokeStyle='#7c3aed';ctx.lineWidth=3;ctx.beginPath();
for(var i=0;i<nShow;i++){if(i===0)ctx.moveTo(bx[i],by[i]);else ctx.lineTo(bx[i],by[i]);}ctx.stroke();
for(var i=8;i<=12&&i<nShow;i++){ctx.fillStyle='#d97706';ctx.beginPath();ctx.arc(bx[i],by[i],4.5,0,6.283);ctx.fill();}
var pp=ease((lt-2.0)/1.2);
if(lt>=2.0){var qx=[],qy=[];for(var i=0;i<N;i++){var sc=(100-D.pl[i])*0.9*pp;qx.push(bx[i]+D.nx[i]*sc);qy.push(by[i]+D.ny[i]*sc);}
ctx.strokeStyle='#cbd5e1';ctx.lineWidth=1;for(var i=0;i<N;i++){ctx.beginPath();ctx.moveTo(bx[i],by[i]);ctx.lineTo(qx[i],qy[i]);ctx.stroke();}
ctx.strokeStyle='#0284c7';ctx.lineWidth=2;ctx.beginPath();for(var i=0;i<N;i++){if(i===0)ctx.moveTo(qx[i],qy[i]);else ctx.lineTo(qx[i],qy[i]);}ctx.stroke();
for(var i=0;i<N;i++){ctx.fillStyle=afc(D.pl[i]);ctx.beginPath();ctx.arc(qx[i],qy[i],3.5,0,6.283);ctx.fill();}}
ctx.font='11px sans-serif';ctx.fillStyle='#7c3aed';ctx.fillText('— design',px+6,py+ph-34);ctx.fillStyle='#0284c7';ctx.fillText('— prediction (dots: pLDDT)',px+6,py+ph-20);ctx.fillStyle='#d97706';ctx.fillText('● motif residues',px+6,py+ph-6);ctx.font='12px sans-serif';
var ns=Math.floor(cl((lt-1.0)/0.8)*N);var sq='';for(var i=0;i<ns;i++)sq+=seqs[di][i];
ctx.fillStyle='#059669';ctx.fillText('seq: ' + sq,px+6,py+14);
var sy=py+ph+14,sh=34;ctx.fillStyle='#1a1a1d';ctx.fillText('per-residue pLDDT',px,sy-4+0);
var cw=pw/N;for(var i=0;i<N;i++){var v=D.pl[i];var h=lt>=2.0?sh*(v/100)*pp:0;ctx.fillStyle=afc(v);ctx.fillRect(px+i*cw+1,sy+8+sh-h,cw-2,h);}
ctx.strokeStyle='#1a1a1d';ctx.lineWidth=1;ctx.strokeRect(px,sy+8,pw,sh);
var ty=sy+8+sh*(1-0.8);ctx.strokeStyle='#e11d48';ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(px,ty);ctx.lineTo(px+pw,ty);ctx.stroke();ctx.setLineDash([]);
ctx.fillStyle='#e11d48';ctx.font='11px sans-serif';ctx.textAlign='right';ctx.fillText('80',px-3,ty);ctx.textAlign='left';ctx.font='12px sans-serif';
var mx=W*0.56+34,mw=W-mx-14;var mp=ease((lt-3.3)/1.0);
ctx.fillStyle='#1a1a1d';ctx.fillText('Success criteria (prediction vs design)',mx,py-12);
var rh=ph/4.2;
for(var k=0;k<4;k++){var m=metrics[k];var y=py+k*rh+4;var val=D.vals[k];var ok=m.hi?val>m.thr:val<m.thr;var col=ok?'#059669':'#e11d48';
ctx.fillStyle='#1a1a1d';ctx.fillText(m.n,mx,y+8);
ctx.textAlign='right';ctx.fillStyle=mp>0.02?col:'#1a1a1d';ctx.fillText((val*mp).toFixed(1)+m.u,mx+mw,y+8);ctx.textAlign='left';
ctx.fillStyle='#eeeef1';ctx.fillRect(mx,y+20,mw,10);
ctx.fillStyle=mp>0.02?col:'#bbbbc2';ctx.fillRect(mx,y+20,mw*cl(val/m.max)*mp,10);
var tx=mx+mw*m.thr/m.max;ctx.strokeStyle='#1a1a1d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(tx,y+16);ctx.lineTo(tx,y+34);ctx.stroke();
ctx.font='11px sans-serif';ctx.fillStyle='#52525b';ctx.textAlign='center';ctx.fillText(m.lab,tx,y+43);ctx.textAlign='left';ctx.font='12px sans-serif';
if(mp>=1){ctx.fillStyle=col;ctx.fillText(ok?'✓':'✗',mx-18,y+25);}}
var vp=ease((lt-4.3)/0.5);
if(vp>0){ctx.globalAlpha=vp;ctx.fillStyle=pass?'#059669':'#e11d48';ctx.font='bold 14px sans-serif';ctx.fillText(pass?'SUCCESS: self-consistent':'FAIL: not reproduced',mx,py+ph+22);ctx.font='12px sans-serif';ctx.globalAlpha=1;}
var msg=stage===0?'Step 1: RFdiffusion samples a backbone':stage===1?'Step 2: ProteinMPNN designs a sequence for it':stage===2?'Step 3: predictor refolds the sequence; dots show confidence':'Step 4: compare prediction with design against thresholds';
ctx.fillStyle='#1a1a1d';ctx.textAlign='left';ctx.fillText('t = ' + t.toFixed(1) + ' s   ' + msg,12,H-12);
}
return {draw:draw};
